content.css:
.cover { position: relative; width: 780px; height: 585px; overflow: hidden; background: #f5f5f5; }
.cover__bg { position: absolute; inset: 0; background: linear-gradient(135deg, #f8f8f8 0%, #e8e8e8 100%); }
@keyframes fadeInUp { from { opacity: 0; margin-top: 20px; } to { opacity: 1; margin-top: 0; } }
.cover__title { position: absolute; top: 46%; left: 0; right: 0; text-align: center; font-size: 56px; font-weight: 800; color: #1a1a1a; margin: 0; letter-spacing: -1px; animation: fadeInUp 0.8s cubic-bezier(0.4, 0, 0.2, 1) forwards; }
.cover__subtitle { position: absolute; top: 56%; left: 0; right: 0; text-align: center; font-size: 24px; font-weight: 400; color: #666; margin: 0; animation: fadeInUp 0.6s 0.3s cubic-bezier(0.4, 0, 0.2, 1) forwards; }
.cover__watermark { position: absolute; left: 50%; top: 50%; margin-left: -90px; margin-top: -12px; padding: 8px 16px; border-radius: 6px; font-size: 14px; font-weight: 600; color: #fff; background: rgba(0,0,0,0.45); letter-spacing: 0.1em; z-index: 2; }
